class EnhancedMessagesScreen extends StatefulWidget{const EnhancedMessagesScreen({super.key});@override State<EnhancedMessagesScreen> createState()=>_EnhancedMessagesScreenState();}
class _EnhancedMessagesScreenState extends State<EnhancedMessagesScreen>{late Future<List<Map<String,dynamic>>> f;@override void initState(){super.initState();f=_load();}Future<List<Map<String,dynamic>>> _load()async{final b=OpenBackend.instance,me=b.userId,ms=await b.activeMatches(),o=<Map<String,dynamic>>[];for(final m in ms){final id=m['user_a']==me?m['user_b']:m['user_a'],p=await b.client.from('profiles').select('id,display_name,avatar_url').eq('id',id).maybeSingle();o.add({...m,'p':p,'last':await b.lastMessage(m['id'].toString())});}return o;}@override Widget build(BuildContext c)=>SafeArea(child:FutureBuilder<List<Map<String,dynamic>>>(future:f,builder:(c,s){if(!s.hasData)return const Center(child:CircularProgressIndicator());return ListView(padding:const EdgeInsets.all(20),children:[const ui.PageTitle('Mesajlar','Bağlantıların burada.'),const SizedBox(height:18),for(final m in s.data!)ListTile(onTap:()=>Navigator.push(c,MaterialPageRoute(builder:(_)=>EnhancedChatScreen(matchId:m['id'].toString(),profile:Map<String,dynamic>.from(m['p']??{})))),leading:CircleAvatar(backgroundImage:(m['p']?['avatar_url']??'').toString().isNotEmpty?NetworkImage(m['p']['avatar_url']):null),title:Text((m['p']?['display_name']??'Open kullanıcısı').toString(),style:const TextStyle(fontWeight:FontWeight.w900)),subtitle:Text((m['last']?['body']??'Yeni bağlantı').toString(),maxLines:1,overflow:TextOverflow.ellipsis),trailing:const Icon(Icons.chevron_right_rounded))]);}));}

class EnhancedChatScreen extends StatefulWidget{const EnhancedChatScreen({super.key,required this.matchId,required this.profile});final String matchId;final Map<String,dynamic> profile;@override State<EnhancedChatScreen> createState()=>_Chat();}
class _Chat extends State<EnhancedChatScreen>{final input=TextEditingController();Timer? t;DateTime? end;Duration left=Duration.zero;bool loading=true,full=false,busy=false,amKeySender=false,requestPending=false;@override void initState(){super.initState();_init();}@override void dispose(){t?.cancel();input.dispose();super.dispose();}Future<void> _init()async{final b=OpenBackend.instance,s=await b.startTrialChat(widget.matchId),m=await b.client.from('matches').select('key_request_id,unlock_requested_by').eq('id',widget.matchId).single(),kr=await b.client.from('key_requests').select('sender_id').eq('id',m['key_request_id']).single();end=DateTime.tryParse(s['trial_ends_at']?.toString()??'');full=s['fully_unlocked_at']!=null;amKeySender=kr['sender_id']==b.userId;requestPending=m['unlock_requested_by']!=null;loading=false;_tick();t=Timer.periodic(const Duration(seconds:1),(_)=>_tick());}void _tick(){if(full)return;final d=end?.toUtc().difference(DateTime.now().toUtc())??Duration.zero;if(mounted)setState(()=>left=d.isNegative?Duration.zero:d);}bool get locked=>!loading&&!full&&left==Duration.zero;String get clock=>'${left.inMinutes.toString().padLeft(2,'0')}:${(left.inSeconds%60).toString().padLeft(2,'0')}';Future<void> send()async{final x=input.text.trim();if(x.isEmpty||busy||locked)return;if(!full&&OpenBackend.instance.containsExternalContact(x)){ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('🔒 İlk sohbet sırasında telefon, sosyal medya kullanıcı adı veya dış bağlantı paylaşamazsın.')));return;}input.clear();setState(()=>busy=true);try{await OpenBackend.instance.sendMessage(widget.matchId,x);}catch(e){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('$e')));}finally{if(mounted)setState(()=>busy=false);}}Future<void> extend(int minutes)async{setState(()=>busy=true);try{final s=await OpenBackend.instance.extendTrialChat(widget.matchId,minutes);end=DateTime.tryParse(s['trial_ends_at']?.toString()??'');_tick();if(mounted)Navigator.pop(context);}finally{if(mounted)setState(()=>busy=false);}}Future<void> options()async{await showModalBottomSheet(context:context,isScrollControlled:true,builder:(c)=>Padding(padding:const EdgeInsets.all(24),child:Column(mainAxisSize:MainAxisSize.min,crossAxisAlignment:CrossAxisAlignment.start,children:[const Text('Sohbete devam et ⚡',style:TextStyle(fontSize:25,fontWeight:FontWeight.w900)),const SizedBox(height:6),Text(amKeySender?'Ek süre al veya kalan 2 soruyu cevaplayıp karşı tarafa onaya gönder.':'Anahtarı gönderen kişi kalan 2 soruyu cevapladığında onay isteği Anahtarlar bölümüne gelecek.',style:const TextStyle(color:ui.OpenApp.muted)),const SizedBox(height:18),ListTile(tileColor:ui.OpenApp.soft,shape:RoundedRectangleBorder(borderRadius:BorderRadius.circular(20)),title:const Text('+10 dakika',style:TextStyle(fontWeight:FontWeight.w900)),trailing:const Text('9,99 TL',style:TextStyle(fontWeight:FontWeight.w900)),onTap:()=>extend(10)),const SizedBox(height:10),ListTile(tileColor:ui.OpenApp.soft,shape:RoundedRectangleBorder(borderRadius:BorderRadius.circular(20)),title:const Text('+30 dakika',style:TextStyle(fontWeight:FontWeight.w900)),trailing:const Text('19,99 TL',style:TextStyle(fontWeight:FontWeight.w900)),onTap:()=>extend(30)),if(amKeySender)...[const SizedBox(height:12),SizedBox(width:double.infinity,child:FilledButton(onPressed:requestPending?null:()async{Navigator.pop(c);final sent=await Navigator.push<bool>(context,MaterialPageRoute(builder:(_)=>UnlockQuestionsScreen(matchId:widget.matchId,otherProfile:widget.profile)));if(sent==true&&mounted)setState(()=>requestPending=true);},child:Text(requestPending?'Onay bekleniyor 🔑':'Kalan 2 soruyu cevapla 🔑🔑')))],const SizedBox(height:10),const Text('Ek süre paketleri ödeme entegrasyonu tamamlanana kadar test modundadır.',style:TextStyle(fontSize:11,color:ui.OpenApp.muted))])));}@override Widget build(BuildContext c){final me=OpenBackend.instance.userId;return Scaffold(backgroundColor:Colors.white,appBar:AppBar(backgroundColor:Colors.white,title:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text((widget.profile['display_name']??'Open').toString(),style:const TextStyle(fontWeight:FontWeight.w900)),Text(full?'Tam kilit açık 🔓':locked?'Süre doldu 🔒':'İlk sohbet · $clock',style:const TextStyle(fontSize:12,color:ui.OpenApp.muted))])),body:Column(children:[if(!full&&!locked)Container(width:double.infinity,padding:const EdgeInsets.symmetric(vertical:7,horizontal:14),color:ui.OpenApp.soft,child:const Text('🔒 Telefon, sosyal medya kullanıcı adı ve dış bağlantılar tam kilit açılana kadar gizlidir.',textAlign:TextAlign.center,style:TextStyle(fontSize:11,fontWeight:FontWeight.w700))),Expanded(child:StreamBuilder<List<Map<String,dynamic>>>(stream:OpenBackend.instance.messageStream(widget.matchId),builder:(c,s){if(!s.hasData)return const Center(child:CircularProgressIndicator());return ListView(padding:const EdgeInsets.all(18),children:[for(final m in s.data!)Align(alignment:m['sender_id']==me?Alignment.centerRight:Alignment.centerLeft,child:Container(margin:const EdgeInsets.only(bottom:8),padding:const EdgeInsets.all(12),decoration:BoxDecoration(color:m['sender_id']==me?ui.OpenApp.lime:ui.OpenApp.soft,borderRadius:BorderRadius.circular(18)),child:Text((m['body']??'').toString()))) ]);})),if(locked)Padding(padding:const EdgeInsets.all(16),child:Column(children:[const Text('15 dakika doldu',style:TextStyle(fontSize:20,fontWeight:FontWeight.w900)),const SizedBox(height:5),Text(requestPending?'2 cevap gönderildi. Karşı tarafın onayı bekleniyor.':amKeySender?'Kalan 2 soruyu cevapla. Karşı taraf onaylarsa sohbet ikiniz için sınırsız açılır.':'Anahtarı gönderen kişi 2 soruyu cevaplayabilir. Onay isteği sana Anahtarlar bölümünden gelir.',textAlign:TextAlign.center),const SizedBox(height:12),SizedBox(width:double.infinity,child:FilledButton(onPressed:options,child:const Text('Devam seçenekleri ⚡')))]))else Padding(padding:const EdgeInsets.all(14),child:Row(children:[Expanded(child:TextField(controller:input,onSubmitted:(_)=>send(),decoration:const InputDecoration(hintText:'Mesaj yaz...'))),IconButton.filled(onPressed:busy?null:send,icon:const Icon(Icons.arrow_upward_rounded))]))]));}}

class UnlockQuestionsScreen extends StatefulWidget{const UnlockQuestionsScreen({super.key,required this.matchId,required this.otherProfile});final String matchId;final Map<String,dynamic> otherProfile;@override State<UnlockQuestionsScreen> createState()=>_U();}
class _U extends State<UnlockQuestionsScreen>{bool loading=true,busy=false;List<Map<String,dynamic>> qs=[];final cs=<String,TextEditingController>{};@override void initState(){super.initState();_load();}Future<void> _load()async{qs=await OpenBackend.instance.remainingQuestions(widget.matchId,widget.otherProfile['id'].toString());for(final q in qs)cs[q['id'].toString()]=TextEditingController();if(mounted)setState(()=>loading=false);}Future<void> submit()async{if(cs.values.any((x)=>x.text.trim().isEmpty))return;setState(()=>busy=true);try{for(final q in qs)await OpenBackend.instance.answerUnlockQuestion(widget.matchId,q['id'].toString(),cs[q['id'].toString()]!.text);await OpenBackend.instance.client.rpc('submit_unlock_request',params:{'p_match_id':widget.matchId});if(mounted){ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('🔑 Cevapların gönderildi. Karşı tarafın Anahtarlar bölümüne düştü.')));Navigator.pop(context,true);}}catch(e){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('$e')));}finally{if(mounted)setState(()=>busy=false);}}@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('Kalan 2 anahtar')),body:loading?const Center(child:CircularProgressIndicator()):ListView(padding:const EdgeInsets.all(20),children:[const Text('Kalan 2 soruyu cevapla',style:TextStyle(fontSize:28,fontWeight:FontWeight.w900)),const SizedBox(height:7),const Text('Cevapların karşı tarafın Anahtarlar bölümüne gider. O onaylarsa sohbet ikiniz için sınırsız açılır.',style:TextStyle(color:ui.OpenApp.muted)),const SizedBox(height:18),for(final q in qs)Padding(padding:const EdgeInsets.only(bottom:16),child:TextField(controller:cs[q['id'].toString()],maxLines:3,decoration:InputDecoration(labelText:q['question'].toString()))),FilledButton(onPressed:busy?null:submit,child:Text(busy?'Gönderiliyor...':'Cevapları onaya gönder 🔑🔑'))]));}
